var i={en:`New listings appear in search after ten minutes; deleted ones linger because the indexing queue stalls. The primary database is correct.`,ua:`Нові оголошення з’являються в пошуку через десять хвилин; видалені лишаються через зупинки черги індексації. Основна база правильна.`};var n={en:[`Trace listing→queue→index lifecycle and find failure points.`,`Add idempotent index updates, retry and reconciliation.`,`Define lag metrics, delete propagation and a freshness SLO.`],ua:[`Простеж listing→queue→index і точки збою.`,`Додай ідемпотентні оновлення індексу, повтори та звірку.`,`Визнач метрики затримки, видалень і SLO актуальності.`]};var t=[{en:`The primary database remains authoritative.`,ua:`Основна база лишається джерелом істини.`},{en:`Replaying an indexing event cannot create duplicate listings.`,ua:`Повтор індексації не породжує дублікати.`}];var s={scenario:i,tasks:n,checks:t};export{t as checks,s as default,i as scenario,n as tasks};